// Follow-up gate for WhatsApp Business and SMS. In-memory state only.
// onInbound records each customer message. check decides whether the assistant may send a follow-up.

const WINDOW_MS = 24 * 60 * 60 * 1000;

// Standard opt-out and opt-in keywords for SMS and WhatsApp programs.
const STOP_WORDS = new Set(["stop", "stopall", "unsubscribe", "cancel", "end", "quit"]);
const START_WORDS = new Set(["start", "unstop"]);

// Reduce a message to letters and digits, lowercased, so "STOP!", " stop. " and "S-T-O-P" compare equal.
// Only the whole message counts as a keyword; "stop by the store" is normal conversation.
function keyword(text) {
  if (typeof text !== "string") return "";
  return text.normalize("NFKC").toLowerCase().replace(/[^\p{L}\p{N}]/gu, "");
}

// userId -> { lastInboundAt: ms since epoch, optedOut: boolean }
const customers = new Map();

export function onInbound(userId, text, at) {
  const atMs = at.getTime();
  const customer = customers.get(userId) ?? { lastInboundAt: -Infinity, optedOut: false };

  // Keep the latest inbound time, in case messages arrive out of order.
  customer.lastInboundAt = Math.max(customer.lastInboundAt, atMs);

  const word = keyword(text);
  if (STOP_WORDS.has(word)) customer.optedOut = true;
  else if (START_WORDS.has(word)) customer.optedOut = false;

  customers.set(userId, customer);
}

export function check(userId, type, now) {
  if (type !== "freeform" && type !== "template") {
    return { allowed: false, rule: "invalid-type" };
  }

  const customer = customers.get(userId);

  // Customers who have never written to us must not be contacted.
  if (!customer) return { allowed: false, rule: "no-prior-inbound" };

  // After STOP, nothing is sent until the customer sends START.
  if (customer.optedOut) return { allowed: false, rule: "opted-out" };

  // Free text is only allowed within 24 hours of the customer's last message.
  // Pre-approved templates are allowed outside that window.
  // The window is measured from the last message; it is closed at exactly 24 hours.
  if (type === "freeform" && now.getTime() - customer.lastInboundAt >= WINDOW_MS) {
    return { allowed: false, rule: "window-closed" };
  }

  return { allowed: true, rule: null };
}

input.command:
node -v && mkdir -p /tmp/bot-test-courier && cat > /tmp/bot-test-courier/test.mjs <<'EOF'
import assert from "node:assert/strict";
import { onInbound, check } from "<HOME>/Desktop/Open-Source/projelerim/proactive-gate/bench/head-to-head/results/round6-heldout-c-haiku/work/courier-inv-g5-1/bot.mjs";

const H = 3600_000;
const t0 = new Date("2026-10-01T10:00:00Z");
const ok = { allowed: true, rule: null };
const no = (rule) => ({ allowed: false, rule });

// never written to us
assert.deepEqual(check("new", "freeform", t0), no("no-prior-inbound"));
assert.deepEqual(check("new", "template", t0), no("no-prior-inbound"));

// ordinary sentences containing a keyword are normal conversation
onInbound("a", "Can you stop by the store tomorrow?", t0);
onInbound("a", "end of the month works", t0);
assert.deepEqual(check("a", "freeform", t0), ok);

// STOP variants, case/spacing/punctuation-insensitive
for (const [i, msg] of ["STOP", " stop! ", "Stop.", "s-t-o-p", "ＳＴＯＰ", "stopall", "UNSUBSCRIBE", "Quit", "cancel"].entries()) {
  const u = "stop" + i;
  onInbound(u, msg, t0);
  assert.deepEqual(check(u, "freeform", t0), no("opted-out"), msg);
  assert.deepEqual(check(u, "template", t0), no("opted-out"), msg);
}

// after STOP, the customer's later messages do not reopen anything except START
onInbound("stop0", "hello again", new Date(t0.getTime() + H));
assert.deepEqual(check("stop0", "template", t0), no("opted-out"));

// START / UNSTOP restore sending
onInbound("stop0", "  start ", new Date(t0.getTime() + 2 * H));
assert.deepEqual(check("stop0", "freeform", new Date(t0.getTime() + 2 * H)), ok);
onInbound("stop1", "Unstop", t0);
assert.deepEqual(check("stop1", "template", t0), ok);

// 24h window for freeform; templates outside the window
onInbound("w", "hi", t0);
assert.deepEqual(check("w", "freeform", new Date(t0.getTime() + 24 * H - 1)), ok);
assert.deepEqual(check("w", "freeform", new Date(t0.getTime() + 24 * H)), no("window-closed"));
assert.deepEqual(check("w", "template", new Date(t0.getTime() + 72 * H)), ok);

// a fresh inbound reopens the window
onInbound("w", "still there", new Date(t0.getTime() + 30 * H));
assert.deepEqual(check("w", "freeform", new Date(t0.getTime() + 50 * H)), ok);

// out-of-order arrival keeps the latest message time
onInbound("o", "one", new Date(t0.getTime() + 10 * H));
onInbound("o", "two", t0);
assert.deepEqual(check("o", "freeform", new Date(t0.getTime() + 20 * H)), ok);

// null / media body is not a keyword
onInbound("m", null, t0);
assert.deepEqual(check("m", "freeform", t0), ok);

// unknown type
assert.deepEqual(check("m", "sms-blast", t0), no("invalid-type"));

console.log("all checks passed");
EOF
node /tmp/bot-test-courier/test.mjs
